from taf.collectors.tcpdump.factory import TcpdumpCollectorFactorySelector, PdumpMirrorCollectorFactory

from taf.collectors.core import core
from robot.utils.robottypes import is_truthy
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class tcpdump(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def _create_factory_selector(self, factory_selector_class):
        return factory_selector_class()

    @staticmethod
    def _convert_bool_in_dict(parameters):
        configuration = {}
        for key, value in parameters.items():
            if value is not None:
                if key == 'capture_locally':
                    configuration[key] = is_truthy(value)
                elif isinstance(value, dict):
                    configuration[key] = tcpdump._convert_bool_in_dict(value)
                else:
                    configuration[key] = value
        return configuration

    def _create_collector_and_set_alias(
            self,
            collector_type,
            factory_selector_class,
            parameters):
        configuration = self._convert_bool_in_dict(parameters=parameters)
        logger.info("Creating {collector_type} Collector with alias name: {name}".format(
            collector_type=collector_type,
            name=configuration['name']))
        factory_selector = self._create_factory_selector(
            factory_selector_class=factory_selector_class)
        tcpdump_collector = factory_selector.create(
            configuration=configuration,
            existing_arguments={})
        self.set_alias(parameters['name'], tcpdump_collector)
        logger.info("{} Collector created successfully".format(collector_type))

    def create_tcpdump_collector(self,
                                 name,
                                 container=None,
                                 kubectl_exec_options=None,
                                 **kwargs):
        """
        Create Tcpdump Collector.

        :param str name: name of collector
        :param str container: (optional) container name substring if tcpdump needs to be run under
            LXC container using lxc-attach.
            "container" is deprecated for "create_tcpdump_collector",
            use "create_lxc_tcpdump_collector" instead.

        :param str kubectl_exec_options: (optional) "kubectl exec" command options (without -t, -i, or -ti).
            "kubectl_exec_options" is deprecated for "create_tcpdump_collector",
            use "create_k8s_kubectl_tcpdump_collector" instead.
        :param kwargs:

            * **options** (*str*): (optional) tcpdump options (except for "-C", "-G", "-w", "-W"), default: empty string
            * **tcpdump_path** (*str*) : (optional) path of tcpdump executable, default value: "tcpdump"
            * **target_file_name** (*str*) : (optional) file name part of the path under which the pcap file is stored
              locally during collect_collectors, default: "[collector_name].pcap"
            * **executor** (*dict*) : (optional) setup info like host, user, password, proxy and port
            * **sudo_password** (*str*) : (optional) password for sudo
            * **capture_locally** (*str*): (optional) for pcap file capture in localhost. This parameter should be
              passed with executor (ex. "true" or "false"), default value is "false"
            * **start_timeout** (*float*) : (optional) start timeout (in seconds) is the time to wait after starting the
              process for the "dropped privs" or "listening on" message, default value is '10'
            * **stop_timeout** (*float*) : (optional)  stop timeout (in seconds) is the time to wait after killing the
              process, default value is '3'

        :Please note: capture_locally='True' is sending the captured data via SSH to the local host. So consider this
                     traffic in capture filter to avoid streaming packets recording.

        .. code-block:: robotframework

            *** Settings ***
            Library    taf.collectors.tcpdump    WITH NAME    tcpdump
            Library    taf.collectors.core    WITH NAME    core

            *** Test Cases ***
            Get TcpdumpLogs from Remote machine
                ${executor_oam_vm}=  Create Dictionary
                ...  host=10.43.204.207
                ...  user=robot
                ...  password=rastre1
                tcpdump.create_tcpdump_collector
                ...     name=tcpdump
                ...     options=-i internal
                ...     executor=${executor_oam_vm}
                core.setup_collectors    names=tcpdump
                core.start_collectors    names=tcpdump
                sleep    10s
                core.stop_collectors    names=tcpdump
                core.collect_collectors    names=tcpdump
                core.teardown_collectors    names=tcpdump

            Get TcpdumpLogs from Remote machine with local capture
                ${executor_oam_vm}=  Create Dictionary
                ...  host=10.43.204.207
                ...  user=robot
                ...  password=rastre1
                tcpdump.create_tcpdump_collector
                ...     name=tcpdump
                ...     options=-i internal not port 22
                ...     executor=${executor_oam_vm}
                ...     capture_locally=yes
                core.setup_collectors    names=tcpdump
                core.start_collectors    names=tcpdump
                sleep    10s
                core.stop_collectors    names=tcpdump
                core.collect_collectors    names=tcpdump
                core.teardown_collectors    names=tcpdump

            Get TcpdumpLogs from Local machine
                tcpdump.create_tcpdump_collector
                ...    name=tcpdump
                ...    options=-i internal
                ...    sudo_password=ute
                core.setup_collectors    names=tcpdump
                core.start_collectors    names=tcpdump
                sleep    10s
                core.stop_collectors    names=tcpdump
                core.collect_collectors    names=tcpdump
                core.teardown_collectors    names=tcpdump

        For more Examples please refer:
        https://confluence.int.net.nokia.com/display/CV/Tcpdump_Collectors+Example

        For more detail on Collectors please refer:
        https://confluence.int.net.nokia.com/display/CV/_Collector+Concepts
        """
        if container or kubectl_exec_options:
            logger.warning("Parameters 'container' and 'kubectl_exec_options' are deprecated, use "
                           "'create_lxc_tcpdump_collector' for container and "
                           "'create_k8s_kubectl_tcpdump_collector'"
                           " for kubectl_exec_options.")
        self._create_collector_and_set_alias(
            collector_type='tcpdump',
            factory_selector_class=TcpdumpCollectorFactorySelector,
            parameters=dict(
                name=name,
                container=container,
                kubectl_exec_options=kubectl_exec_options,
                **kwargs))

